// ─── File: src/main/java/com/bank/transfer/model/SafeAccount.java ───
// ✅ WITH ENCAPSULATION — private fields, validated methods
package com.bank.transfer.model;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.logging.Logger;

public class SafeAccount {
    private static final Logger log = Logger.getLogger(SafeAccount.class.getName());

    // ENCAPSULATED: private fields — controlled access only
    private final String accountId;
    private BigDecimal balance;
    private String status;
    private final List<String> auditTrail = new ArrayList<>();

    public SafeAccount(String accountId, BigDecimal initialBalance) {
        if (accountId == null || accountId.isBlank()) throw new IllegalArgumentException("accountId required");
        if (initialBalance.signum() < 0) throw new IllegalArgumentException("Initial balance cannot be negative");
        this.accountId = accountId;
        this.balance = initialBalance;
        this.status = "ACTIVE";
        auditTrail.add("OPENED with Rs." + initialBalance);
    }

    // ENCAPSULATED deposit: validates + audits
    public void deposit(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Deposit must be positive");
        if (!"ACTIVE".equals(status)) throw new IllegalStateException("Account " + accountId + " is " + status);
        balance = balance.add(amount);
        auditTrail.add("CREDIT Rs." + amount + " → balance Rs." + balance);
        log.info("[SAFE] " + accountId + " deposited Rs." + amount);
    }

    // ENCAPSULATED withdraw: validates balance + status + audit
    public void withdraw(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Withdrawal must be positive");
        if (!"ACTIVE".equals(status)) throw new IllegalStateException("Account " + accountId + " is " + status);
        if (balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient balance: Rs." + balance + " for Rs." + amount);
        }
        balance = balance.subtract(amount);
        auditTrail.add("DEBIT Rs." + amount + " → balance Rs." + balance);
        log.info("[SAFE] " + accountId + " withdrew Rs." + amount);
    }

    public void freeze() {
        status = "FROZEN";
        auditTrail.add("FROZEN");
    }

    // READ-ONLY access — no setBalance!
    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
    public List<String> getAuditTrail() { return Collections.unmodifiableList(auditTrail); }
}
