// ─── File: src/test/java/com/bank/transfer/model/EncapsulationTest.java ───
package com.bank.transfer.model;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class EncapsulationTest {

    // ═══ WITHOUT ENCAPSULATION — data can be CORRUPTED ═══
    @Test
    void unsafeAccount_balanceCanBeCorrupted() {
        UnsafeAccount unsafe = new UnsafeAccount("SAV001", new BigDecimal("10000"));

        // ❌ BUG: anyone can set balance directly!
        unsafe.balance = new BigDecimal("-999999");  // NEGATIVE balance!
        assertThat(unsafe.balance).isNegative();     // DATA CORRUPTED!

        unsafe.status = "ALIEN_ADMIN";  // invalid status!
        assertThat(unsafe.status).isEqualTo("ALIEN_ADMIN");  // CORRUPTED!
        // No validation. No audit. Nothing stopped this.
    }

    // ═══ WITH ENCAPSULATION — data is PROTECTED ═══
    @Test
    void safeAccount_balanceCannotBeSetDirectly() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));

        // safe.balance = -999999;  // WON'T COMPILE! balance is private.

        // Must use methods — which VALIDATE:
        safe.deposit(new BigDecimal("5000"));
        assertThat(safe.getBalance()).isEqualByComparingTo("15000");
    }

    @Test
    void safeAccount_negativeDepositRejected() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));
        assertThatThrownBy(() -> safe.deposit(new BigDecimal("-100")))
            .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void safeAccount_overdraftRejected() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));
        assertThatThrownBy(() -> safe.withdraw(new BigDecimal("50000")))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("Insufficient");
    }

    @Test
    void safeAccount_frozenAccountRejected() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));
        safe.freeze();
        assertThatThrownBy(() -> safe.deposit(new BigDecimal("5000")))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("FROZEN");
    }

    @Test
    void safeAccount_auditTrailTracksAllChanges() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));
        safe.deposit(new BigDecimal("5000"));
        safe.withdraw(new BigDecimal("3000"));
        // Audit trail: OPENED, CREDIT, DEBIT — 3 entries
        assertThat(safe.getAuditTrail()).hasSize(3);
        assertThat(safe.getAuditTrail().get(1)).contains("CREDIT");
        assertThat(safe.getAuditTrail().get(2)).contains("DEBIT");
    }

    @Test
    void safeAccount_auditTrailIsUnmodifiable() {
        SafeAccount safe = new SafeAccount("SAV001", new BigDecimal("10000"));
        assertThatThrownBy(() -> safe.getAuditTrail().add("HACK!"))
            .isInstanceOf(UnsupportedOperationException.class);
    }
}
